const raw = String($json.ip ?? '').trim();
function v4(s) {
 const p=s.split('.');
 if(p.length!==4 || p.some(x=>! /^(0|[1-9][0-9]{0,2})$/.test(x)||Number(x)>255)) return null;
 return p.map(Number);
}
function v6(s) {
 if(!s.includes(':')||s.includes('%')||s.includes('.')||!/^[0-9a-f:]+$/i.test(s)) return null;
 const halves=s.toLowerCase().split('::');
 if(halves.length>2) return null;
 const a=halves[0]?halves[0].split(':'):[];
 const b=halves.length===2&&halves[1]?halves[1].split(':'):[];
 if([...a,...b].some(x=>! /^[0-9a-f]{1,4}$/.test(x)))return null;
 if(halves.length===1&&a.length!==8 || halves.length===2&&a.length+b.length>=8)return null;
 return halves.length===1?a.map(x=>parseInt(x,16)):[...a.map(x=>parseInt(x,16)),...Array(8-a.length-b.length).fill(0),...b.map(x=>parseInt(x,16))];
}
const a=v4(raw), b=a?null:v6(raw);
let eligible=false, reason='Invalid IP address. Enter one IPv4 or IPv6 literal without a port, URL, CIDR or zone ID.', ip=raw, family=null;
